    /// Identity is geometry plus occurrence index in walk order.
    ///
    /// Geometry alone is not identity: a page root and the fullscreen
    /// overlay covering it share x/y/w/h, and keying on that
    /// collapsed them into one node — the overlay inherited the
    /// root's z-position and the replay drew the page *through* it.
    ///
    /// Truncated to integers first, because sub-pixel jitter from a
    /// layout pass that returns floats would make every node new on
    /// every tick, turning a still screen into a stream of full
    /// deltas.
    static func nodeKey(_ node: Node, occurrence: Int) -> String {
        "\(Int(node.x)),\(Int(node.y)),\(Int(node.w)),\(Int(node.h))#\(occurrence)"
    }

    /// Ordered, because a delta's arrays are compared against the
    /// TypeScript ring's and a dictionary would shuffle them.
    static func index(_ nodes: [Node]) -> [(key: String, node: Node, at: Int)] {
