        var out: [(key: String, node: Node, at: Int)] = []
        for (at, node) in nodes.enumerated() {
            let base = nodeKey(node, occurrence: 0).components(separatedBy: "#")[0]
            let occurrence = seen[base] ?? 0
            seen[base] = occurrence + 1
            out.append((key: "\(base)#\(occurrence)", node: node, at: at))
        }
        return out
    }

    struct Delta {
        var added: [(node: Node, at: Int, id: String)] = []
        var changed: [(node: Node, id: String)] = []
        var removed: [(node: Node, id: String)] = []

        var count: Int { added.count + changed.count + removed.count }
    }

    /// Position is identity, so a node that moved is a removal and an
    /// addition rather than a change. Only what a wireframe draws —
    /// kind, colour, text — makes an existing node different.
    static func delta(
        from previous: [(key: String, node: Node, at: Int)],
        to current: [(key: String, node: Node, at: Int)]
    ) -> Delta {
        var before: [String: Node] = [:]
        for entry in previous { before[entry.key] = entry.node }
        var now: Set<String> = []
        for entry in current { now.insert(entry.key) }

