            let cold = lastState == nil
            let overdue = frame.ts - lastKeyframeTs >= keyframeMs

            var entry: [String: Any]
            if cold || overdue {
                entry = keyframe(frame)
            } else {
                let diff = delta(from: lastState!, to: state)
                if diff.count == 0 { return nil }
                if state.count >= keyframeRatioMinNodes
                    && Double(diff.count) >= Double(state.count) * deltaToKeyframeRatio
                {
                    entry = keyframe(frame)
                } else {
                    entry = [
                        "ts": frame.ts,
                        "kind": "delta",
                        "added": diff.added.map { encode($0.node, extra: ["at": $0.at, "id": $0.id]) },
                        "changed": diff.changed.map { encode($0.node, extra: ["id": $0.id]) },
                        "removed": diff.removed.map {
