        /// against a state the player no longer holds.
        func drain() -> [[String: Any]] {
            lock.lock()
            defer { lock.unlock() }
            let out = entries
            entries = []
            lastState = nil
            lastKeyframeTs = 0
            return out
        }

        private func keyframe(_ frame: Frame) -> [String: Any] {
            lastKeyframeTs = frame.ts
            return [
                "ts": frame.ts,
                "kind": "key",
                "width": frame.width,
                "height": frame.height,
                "nodes": frame.nodes.map { encode($0, extra: [:]) },
