    /// Optional fields are left out rather than sent as null, which is
    /// what `JSON.stringify` does with an absent key — and the player
    /// reads "absent" and "null" the same way only by accident.
    static func encode(_ node: Node, extra: [String: Any]) -> [String: Any] {
